(()=>{
 const config=JSON.parse(document.getElementById('limb-config').textContent),region=config.region,root=document.getElementById(region+'-motion'),by=id=>document.getElementById(region+'-'+id),hub=document.getElementById('hub-config'),hubConfig=hub?JSON.parse(hub.textContent):null,store=config.store,topic=config.topic,views=config.views||['front','side','back'];
 const model=NativeLimbRenderer(root,JSON.parse(document.getElementById('limb-atlas').textContent),region,JSON.parse(document.getElementById('limb-reference').textContent),JSON.parse(document.getElementById('limb-bone-fields').textContent)),sculpt=NativeLimbSculptLayer(root,model.model,region,model.composition),nativeVolumes=root.querySelector('.native-volumes'),nativeLabels=root.querySelector('.native-labels');
 let angle=config.initial,view='front',mode='anatomy',showMuscles=true,playing=false,phase=0,last=0,lastDraw=0,lastCapture=0;
 let saved=hubConfig?.state;try{saved??=JSON.parse(localStorage.getItem(store)||'null');}catch{}const content=saved?.modelContent;if(content?.topic===topic){if(Number.isFinite(content.angle))angle=Math.max(config.min,Math.min(config.max,content.angle));if(views.includes(content.camera))view=content.camera;if(['anatomy','sculpt','compare'].includes(content.mode))mode=content.mode;if(typeof content.showMuscles==='boolean')showMuscles=content.showMuscles;if(typeof content.fibers==='boolean')by('fibers').checked=content.fibers;if(typeof content.transparent==='boolean')by('transparent').checked=content.transparent;playing=saved.privateContent?.playing===true&&!matchMedia('(prefers-reduced-motion: reduce)').matches;}
 const landmarks=model.landmarks;landmarks.restore(content?.landmark);landmarks.onChange(()=>{render();capture();});
 const composition=model.composition;
 function render(){
  if(!root.isConnected)return;root.classList.toggle('no-fibers',!by('fibers').checked);root.classList.toggle('transparent',by('transparent').checked);root.dataset.revision='native-limb-sculpt-v2';root.dataset.angle=Math.round(angle);root.dataset.camera=view;root.dataset.mode=mode;root.dataset.showMuscles=showMuscles;
  model.render(angle,view,mode);sculpt.render(model.debug,view,mode,showMuscles,by('transparent').checked,by('fibers').checked);
  if(mode==='compare')nativeVolumes.setAttribute('clip-path','url(#limb-anatomy-panel)');else nativeVolumes.removeAttribute('clip-path');
  by('angle').value=Math.round(angle);const text=region==='forearm'?(Math.round(angle)===0?'중립 0°':(angle<0?'회외 ':'회내 ')+Math.abs(Math.round(angle))+'°'):(Math.round(angle)===0?'펴짐 0°':'굽힘 '+Math.round(angle)+'°');by('value').textContent=text;by('angle').setAttribute('aria-valuetext',text);for(const v of views)by(v).setAttribute('aria-pressed',v===view);for(const button of root.querySelectorAll('[data-limb-mode]'))button.setAttribute('aria-pressed',button.dataset.limbMode===mode);const muscleButton=root.querySelector('[data-limb-toggle-muscles]');if(muscleButton)muscleButton.textContent=showMuscles?'근육 숨기기':'근육 보이기';by('view-caption').textContent=(view==='medial'?'측면(반대) · 허벅지 안쪽':view==='side'?'측면':view==='front'?'정면'+(region==='thigh'?' 사선':''):'후면'+(region==='thigh'?' 사선':''))+' · '+(region==='forearm'?'오른팔 · 회내·회외':'오른쪽 허벅지 · 무릎 굽힘');
 }
 function capture(){const state={modelContent:{revision:'native-limb-sculpt-v2',topic,angle:Math.round(angle),camera:view,mode,showMuscles,fibers:by('fibers').checked,transparent:by('transparent').checked,landmark:landmarks.value,composition:composition.state},privateContent:{playing}};try{localStorage.setItem(store,JSON.stringify(state));}catch{}if(hubConfig)parent.postMessage({type:'anatomy-hub-state',key:hubConfig.key,state},'*');}
 function play(on){playing=on;by('play').textContent=on?'일시정지':'재생';by('play').setAttribute('aria-pressed',on);last=0;}
 function syncPhase(){phase=Math.acos(Math.max(-1,Math.min(1,1-2*(angle-config.min)/(config.max-config.min))));}
 by('angle').addEventListener('input',()=>{play(false);angle=+by('angle').value;render();capture();});by('play').addEventListener('click',()=>{if(!playing)syncPhase();play(!playing);capture();});
 for(const v of views)by(v).addEventListener('click',()=>{view=v;render();capture();queueFit();});for(const id of ['fibers','transparent'])by(id).addEventListener('change',()=>{render();capture();queueFit();});
 root.querySelectorAll('[data-limb-mode]').forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.limbMode;render();capture();queueFit();}));root.querySelector('[data-limb-toggle-muscles]').addEventListener('click',()=>{showMuscles=!showMuscles;render();capture();queueFit();});
 let pending=false;function fit(){pending=false;if(!root.isConnected)return;const svg=root.querySelector('svg'),viewportWidth=document.documentElement.clientWidth,available=Math.max(0,viewportWidth-32),overhead=root.scrollHeight-svg.getBoundingClientRect().height,width=Math.floor(viewportWidth>=640?available:available<=680?available:Math.min(available,700,Math.max(220,(innerHeight-overhead-48)*600/630)))+'px';if(root.style.width!==width)root.style.width=width;}
 function queueFit(){if(!pending){pending=true;requestAnimationFrame(fit);}}window.addEventListener('resize',queueFit);new ResizeObserver(queueFit).observe(root);new ResizeObserver(render).observe(root);
 function tick(t){if(!root.isConnected)return;if(!playing||document.hidden||root.dataset.hubVisible==='false')last=0;if(playing&&!document.hidden&&root.dataset.hubVisible!=='false'&&t-lastDraw>=1000/30){if(last)phase+=Math.min(t-last,160)*Math.PI/5500;angle=config.min+(config.max-config.min)*(1-Math.cos(phase))/2;render();last=t;lastDraw=t;if(t-lastCapture>=500){capture();lastCapture=t;}}requestAnimationFrame(tick);}requestAnimationFrame(tick);
 window.nativeLimb={model,sculpt,root,setPose(a,v=view){play(false);angle=Math.max(config.min,Math.min(config.max,a));if(views.includes(v))view=v;render();capture();},setMode(value){if(['anatomy','sculpt','compare'].includes(value)){mode=value;render();capture();}},setShowMuscles(value){showMuscles=!!value;render();capture();},get mode(){return mode;}};
 syncPhase();play(playing);render();queueFit();capture();
})();
